from pathlib import Path
import json,html,csv
root=Path('qsl-bench/modernization')
out=root/'results/2026-11-06'
rows=[]
for estimates in sorted((out/'criterion').glob('*/*/new/estimates.json')):
    parent=estimates.parent
    sample=json.loads((parent/'sample.json').read_text())
    estimate=json.loads(estimates.read_text())['slope']
    group,name=parent.parent.parent.name,parent.parent.name
    useful=2048 if 'string' in group else 24
    wire=2052 if 'string' in group else 5 if 'q16' in name.lower() else 24
    t=estimate['point_estimate'];ci=estimate['confidence_interval']
    rows.append(dict(name=name,useful=useful,wire=wire,ns=t,low=ci['lower_bound'],high=ci['upper_bound'],P=useful/t,Plow=useful/ci['upper_bound'],Phigh=useful/ci['lower_bound'],samples=[a/b for a,b in zip(sample['times'],sample['iters'])]))
assert len(rows)==4
meta=json.loads((out/'metadata.json').read_text())
(out/'summary.json').write_text(json.dumps(dict(rows=rows,metadata=meta),indent=2),encoding='utf8')
with (out/'summary.csv').open('w',newline='',encoding='utf8') as f:
    keys=['name','useful','wire','ns','low','high','P','Plow','Phigh'];w=csv.DictWriter(f,fieldnames=keys,extrasaction='ignore');w.writeheader();w.writerows(rows)
tr=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [r['name'],r['useful'],r['wire'],f"{r['ns']:.3f}",f"{r['low']:.3f}–{r['high']:.3f}",f"{r['P']:.3f}"])+'</tr>' for r in rows)
